def encode_default(self, dft: Any) -> Any:
    """Encode a default value to a JSON-serializable value.

    This is used to encode default values for fields in the generated JSON schema.

    Args:
        dft: The default value to encode.

    Returns:
        The encoded default value.
    """
    import ipaddress

    config = self._config
    try:
        return pydantic_core.to_jsonable_python(
            dft,
            timedelta_mode=config.ser_json_timedelta,
            bytes_mode=config.ser_json_bytes,
        )
    except pydantic_core.PydanticSerializationError:
        # Handle IP address types that are not directly serializable
        if isinstance(dft, (ipaddress.IPv4Address, ipaddress.IPv4Interface, ipaddress.IPv4Network,
                           ipaddress.IPv6Address, ipaddress.IPv6Interface, ipaddress.IPv6Network)):
            return str(dft)
        raise

